<script setup lang="ts">import { router, usePage } from '@inertiajs/vue3'; import MainLayout from '../../Layouts/MainLayout.vue'; defineProps<{items:{data:Array<any>;links:Array<any>}}>(); const page=usePage(); const rupiah=(v:number)=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(v); const decide=(id:number,status:'approved'|'rejected')=>{if(status==='rejected'){const reason=window.prompt('Alasan penolakan wajib diisi:');if(!reason?.trim())return;router.patch(`/approval/${id}`,{status,reason});}else if(confirm('Setujui transaksi ini?'))router.patch(`/approval/${id}`,{status,reason:''});};</script>
<template><MainLayout><main class="p-6 sm:p-10"><div class="mx-auto max-w-7xl"><div v-if="page.props.flash?.success" class="mb-5 rounded-xl bg-emerald-50 px-4 py-3 text-sm text-emerald-700">{{ page.props.flash.success }}</div><div class="mb-8"><p class="text-sm font-semibold uppercase tracking-[0.2em] text-teal-700">Kontrol</p><h1 class="mt-2 text-3xl font-bold text-slate-950">Approval workflow</h1><p class="mt-2 text-slate-500">Tinjau transaksi besar sebelum diproses sebagai transaksi final.</p></div><section class="overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200"><div class="border-b border-slate-100 px-6 py-5"><h2 class="font-bold">Menunggu persetujuan</h2><p class="mt-1 text-xs text-slate-500">{{ items.data.length }} transaksi pending di halaman ini</p></div><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="px-6 py-4">Tanggal</th><th class="px-6 py-4">Siswa</th><th class="px-6 py-4">Jumlah</th><th class="px-6 py-4">Peminta</th><th class="px-6 py-4 text-right">Aksi</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="item in items.data" :key="item.id"><td class="px-6 py-4 text-slate-500">{{ item.tanggal }}</td><td class="px-6 py-4 font-semibold">{{ item.siswa }}</td><td class="px-6 py-4 font-bold text-rose-700">{{ rupiah(item.jumlah) }}</td><td class="px-6 py-4 text-slate-500">{{ item.requestedBy }}</td><td class="px-6 py-4 text-right"><button class="mr-2 rounded-lg bg-emerald-600 px-3 py-2 text-xs font-semibold text-white" @click="decide(item.id,'approved')">Setujui</button><button class="rounded-lg bg-rose-600 px-3 py-2 text-xs font-semibold text-white" @click="decide(item.id,'rejected')">Tolak</button></td></tr><tr v-if="!items.data.length"><td colspan="5" class="px-6 py-12 text-center text-slate-400">Tidak ada approval pending.</td></tr></tbody></table></div></section></div></main></MainLayout></template>
